-- No row without a real date, from now on: `date(x)` gives back `x` only for
-- a real `YYYY-MM-DD`, and never for the empty default.
CREATE TRIGGER `time_entries_spent_on_inserted`
BEFORE INSERT ON `time_entries`
FOR EACH ROW
WHEN date(NEW.`spent_on`) IS NOT NEW.`spent_on`
BEGIN
	SELECT RAISE(ABORT, 'an entry has the date of its day');
END;
--> statement-breakpoint
CREATE TRIGGER `time_entries_spent_on_updated`
BEFORE UPDATE OF `spent_on` ON `time_entries`
FOR EACH ROW
WHEN date(NEW.`spent_on`) IS NOT NEW.`spent_on`
BEGIN
	SELECT RAISE(ABORT, 'an entry has the date of its day');
END;
--> statement-breakpoint
